import { defineConfig } from 'orval';

/**
 * Generates this package's code from its own contract snapshot (./openapi.json,
 * refreshed by `npm run contract:fetch`). All input and output stays inside
 * this package. Never edit src/generated by hand.
 */
const input = './openapi.json';
const mutator = { path: './src/fetcher.ts', name: 'apiFetch' };

export default defineConfig({
  // Plain typed functions — no framework dependency (entry: @notes/api-client)
  client: {
    input,
    output: {
      mode: 'single',
      target: './src/generated/client.ts',
      schemas: './src/generated/model',
      client: 'fetch',
      override: { mutator, fetch: { includeHttpResponseReturnType: false } },
    },
  },
  // TanStack Query hooks (entry: @notes/api-client/react)
  react: {
    input,
    output: {
      mode: 'single',
      target: './src/generated/react.ts',
      schemas: './src/generated/model',
      client: 'react-query',
      httpClient: 'fetch',
      override: {
        mutator,
        fetch: { includeHttpResponseReturnType: false },
        // signal: false — orval's generated query functions pass the AbortSignal where the
        // fetch-style functions expect RequestInit. Requests are then not cancelled on
        // unmount; React Query simply ignores the late result.
        query: { useQuery: true, useMutation: true, signal: false },
      },
    },
  },
  // Zod schemas with the API's validation rules (exported as `schemas`)
  zod: {
    input,
    output: {
      mode: 'single',
      target: './src/generated/zod.ts',
      client: 'zod',
    },
  },
});
